function describeSchemaError(error: SchemaError): string {
  const path = error.instancePath ?? error.dataPath ?? '';
  const where = path === '' ? 'input' : `property '${path}'`;
  if (error.keyword === 'required') {
    const missing = error.params?.missingProperty;
    return `${where} is missing required property '${typeof missing === 'string' ? missing : path || 'unknown'}'`;
  }
  if (error.keyword === 'type') {
    const expected = error.params?.type;
    return `${where} must be of type ${typeof expected === 'string' ? expected : 'its declared type'}`;
  }
  if (error.keyword === 'enum') {
    return `${where} must be one of the declared enum values`;
  }
  return error.message ? `${where} ${error.message}` : `${where} does not match its declared schema`;
}
```

